Each summand is $Q$-symmetric and congruent to the identity.
Since $|\mathcal P|^{-1}\in R_0$, the same holds for
$D_{\mathcal P}$, which is therefore invertible.
For $a\in\mathcal P$, reindexing by $r=ap$ gives
\[
 \varphi(a)D_{\mathcal P}
   =\frac1{|\mathcal P|}
      \sum_{p\in\mathcal P}\varphi(ap)p^{-1}
   =\frac1{|\mathcal P|}
      \sum_{r\in\mathcal P}\varphi(r)r^{-1}a
   =D_{\mathcal P}a.
\]

\label{lemma:graph-matrix-not-inner}
\label{lemma:frame-centralizer}
For every commutative $A$-algebra $S$,
\[
\begin{aligned}
 \operatorname{Cent}_{\operatorname{End}_S(L_S)}(\mathcal F_S)
   &=S\pi_+\oplus S\pi_-,\\
 \operatorname{Cent}_{\mathcal G(S)}(\mathcal F_S)
   &=\{I_{78}\}.
\end{aligned}
\]
Moreover, $Q\notin\mathcal G(S)$ whenever $S\ne0$.

\label{corollary:automorphisms-of-G}
\label{cor:full-adjoint-automorphisms}
Every automorphism of $G=G_{\mathrm{ad},\sigma}(E_6,R)$ has the
same unique form $i_g\circ\rho_*$, with $g\in G$ and
$\rho\in\operatorname{Aut}(R,\theta)$.

\label{cor:full-simply-connected-automorphisms}
Every automorphism of $\widetilde G$ is a product of strictly
inner, diagonal, and ring automorphisms.
